-- Synthetic rows, no DML in Auth/admin; all changes roll back.
begin;
create function pg_temp.o_id(n integer) returns uuid language sql immutable as $$select ('fd600000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.o_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;end$$;
create function pg_temp.o_error(statement text,state text) returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate=state then return;end if;raise;end;raise exception 'Expected SQLSTATE %',state;end$$;
create function pg_temp.o_empty() returns jsonb language sql immutable as $$select '{"referee":null,"umpire1":null,"umpire2":null,"scorer":null,"timer":null,"shotClock":null}'::jsonb$$;
create function pg_temp.o_new(n integer,label text,confirmed boolean default false) returns jsonb language sql as $$select jsonb_build_object('kind','new','id',pg_temp.o_id(n),'name',label,'confirmHomonym',confirmed)$$;
create function pg_temp.o_existing(n integer) returns jsonb language sql as $$select jsonb_build_object('kind','existing','id',pg_temp.o_id(n))$$;
create function pg_temp.o_command(n integer,slots jsonb) returns jsonb language sql as $$select jsonb_build_object('commandId',pg_temp.o_id(n),'expectedVersion',0,'game',jsonb_build_object('id',pg_temp.o_id(n+1),'disputeId',pg_temp.o_id(92),'homeRegistrationId',pg_temp.o_id(95),'awayRegistrationId',pg_temp.o_id(96),'date',null,'time',null,'venue',null,'number',null),'officiating',slots)$$;
grant execute on function pg_temp.o_id(integer),pg_temp.o_assert(boolean,text),pg_temp.o_error(text,text),pg_temp.o_empty(),pg_temp.o_new(integer,text,boolean),pg_temp.o_existing(integer),pg_temp.o_command(integer,jsonb) to authenticated,anon;
insert into public.championships(id,name) values(pg_temp.o_id(90),'Officiating fixture');
insert into public.seasons(id,championship_id,year) values(pg_temp.o_id(91),pg_temp.o_id(90),2026);
insert into public.disputes(id,season_id,gender,category) values(pg_temp.o_id(92),pg_temp.o_id(91),'masculino','Adulto');
insert into public.teams(id,name) values(pg_temp.o_id(94),'Officiating team');
insert into public.registrations(id,dispute_id,team_id,name) values(pg_temp.o_id(95),pg_temp.o_id(92),pg_temp.o_id(94),'Officials A'),(pg_temp.o_id(96),pg_temp.o_id(92),pg_temp.o_id(94),'Officials B');
insert into public.games(id,dispute_id,home_registration_id,away_registration_id) values(pg_temp.o_id(1),pg_temp.o_id(92),pg_temp.o_id(95),pg_temp.o_id(96));
-- OFFICIATING_ASSERTIONS
select set_config('request.jwt.claim.sub',(select user_id::text from public.admin_access where enabled order by user_id limit 1),true);
set local role authenticated;
select pg_temp.o_assert(public.get_game_editor(pg_temp.o_id(1))->'officiating'=pg_temp.o_empty(),'legacy game has empty officiating');
select pg_temp.o_assert(not has_table_privilege('authenticated','private.game_officials','INSERT') and not has_table_privilege('authenticated','private.game_official_assignments','SELECT'),'private catalog and assignments');
select pg_temp.o_assert(not has_function_privilege('anon','public.get_game_editor(uuid)','EXECUTE') and not has_function_privilege('anon','public.list_game_officials(text,integer)','EXECUTE'),'not public');
select public.save_game_editor(pg_temp.o_command(100,pg_temp.o_empty()));
select public.save_game_editor(pg_temp.o_command(102,jsonb_set(pg_temp.o_empty(),'{referee}',pg_temp.o_new(500,' João   Silva '))));
select public.save_game_editor(pg_temp.o_command(102,jsonb_set(pg_temp.o_empty(),'{referee}',pg_temp.o_new(500,' João   Silva '))));
select pg_temp.o_assert(public.get_game_editor(pg_temp.o_id(103))#>>'{officiating,referee,name}'='João Silva','snapshot normalized');
select pg_temp.o_assert(jsonb_array_length(public.list_game_officials('JOAO SILVA',0)->'items')=1,'accent-insensitive lookup and replay no duplicate');
select pg_temp.o_assert(not(public.get_game(pg_temp.o_id(103)) ? 'officiating'),'legacy game DTO unchanged');
select pg_temp.o_error(format('select public.save_game_editor(%L::jsonb)',pg_temp.o_command(104,jsonb_set(pg_temp.o_empty(),'{umpire1}',pg_temp.o_new(501,'Gap')))),'PT400');
select pg_temp.o_error(format('select public.save_game_editor(%L::jsonb)',pg_temp.o_command(106,jsonb_set(pg_temp.o_empty(),'{shotClock}',pg_temp.o_new(501,'Gap')))),'PT400');
select pg_temp.o_assert(public.list_game_officials('Gap',0)->'items'='[]'::jsonb,'gaps do not create people');
select pg_temp.o_error(format('select public.save_game_editor(%L::jsonb)',pg_temp.o_command(108,jsonb_set(pg_temp.o_empty(),'{referee}',pg_temp.o_new(501,'JOAO SILVA')))),'PT409');
select public.save_game_editor(pg_temp.o_command(110,jsonb_set(pg_temp.o_empty(),'{scorer}',pg_temp.o_new(501,'JOAO SILVA',true))));
select pg_temp.o_assert(jsonb_array_length(public.list_game_officials('joao silva',0)->'items')=2,'confirmed homonyms are distinct identities');
select public.save_game_editor(pg_temp.o_command(112,jsonb_set(pg_temp.o_empty(),'{referee}',pg_temp.o_existing(500))));
select pg_temp.o_error(format('select public.save_game_editor(%L::jsonb)',pg_temp.o_command(114,jsonb_set(jsonb_set(pg_temp.o_empty(),'{referee}',pg_temp.o_existing(500)),'{scorer}',pg_temp.o_existing(500)))),'PT400');
select pg_temp.o_error(format('select public.save_game_editor(%L::jsonb)',pg_temp.o_command(116,jsonb_set(pg_temp.o_empty(),'{referee}',pg_temp.o_existing(999)))),'PT400');
select pg_temp.o_error(format('select public.save_game_editor(%L::jsonb)',jsonb_set(pg_temp.o_command(118,jsonb_set(pg_temp.o_empty(),'{referee}',pg_temp.o_new(502,'Never committed'))),'{game,awayRegistrationId}',to_jsonb(pg_temp.o_id(95)))),'PT400');
select pg_temp.o_assert(public.list_game_officials('Never committed',0)->'items'='[]'::jsonb,'invalid game cannot create official');
select pg_temp.o_error(format('select public.save_game_editor(%L::jsonb)',pg_temp.o_command(130,jsonb_set(jsonb_set(pg_temp.o_empty(),'{referee}',pg_temp.o_new(502,'Late rollback')),'{umpire1}',pg_temp.o_existing(999)))),'PT400');
select pg_temp.o_assert(public.list_game_officials('Late rollback',0)->'items'='[]'::jsonb and public.get_game_editor(pg_temp.o_id(131)) is null,'late invalid identity rolls back both official and game');
select pg_temp.o_error(format('select public.save_game_editor(%L::jsonb)',jsonb_set(pg_temp.o_command(102,pg_temp.o_empty()),'{officiating}',pg_temp.o_empty())),'PT409');
-- Old writer remains supported and cannot silently erase existing assignments.
select public.save_game(jsonb_set(jsonb_set(pg_temp.o_command(120,pg_temp.o_empty())-'officiating','{game,id}',to_jsonb(pg_temp.o_id(103))),'{expectedVersion}','1'));
select pg_temp.o_assert(public.get_game_editor(pg_temp.o_id(103))#>>'{officiating,referee,name}'='João Silva','legacy writer preserves assignments');
select pg_temp.o_error(format('select public.save_game_editor(%L::jsonb)',jsonb_set(jsonb_set(pg_temp.o_command(122,jsonb_set(pg_temp.o_empty(),'{referee}',pg_temp.o_new(502,'Stale official'))),'{game,id}',to_jsonb(pg_temp.o_id(103))),'{expectedVersion}','1')),'PT409');
select pg_temp.o_assert(public.list_game_officials('Stale official',0)->'items'='[]'::jsonb,'stale game cannot create official');
-- Reusing an old writer command ID in the versioned writer must not add a scale after its ACK.
select public.save_game(pg_temp.o_command(124,pg_temp.o_empty())-'officiating');
select pg_temp.o_error(format('select public.save_game_editor(%L::jsonb)',pg_temp.o_command(124,jsonb_set(pg_temp.o_empty(),'{referee}',pg_temp.o_existing(500)))),'PT409');
select pg_temp.o_assert(public.get_game_editor(pg_temp.o_id(125))->'officiating'=pg_temp.o_empty(),'legacy ACK cannot be extended');
select public.save_game_editor(jsonb_set(jsonb_set(pg_temp.o_command(126,pg_temp.o_empty()),'{game,id}',to_jsonb(pg_temp.o_id(103))),'{expectedVersion}','2'));
select pg_temp.o_assert(public.get_game_editor(pg_temp.o_id(103))->'officiating'=pg_temp.o_empty(),'explicit clear persists');
do $$declare slots jsonb:=pg_temp.o_empty();role text;n integer:=600;begin foreach role in array array['referee','umpire1','umpire2','scorer','timer','shotClock'] loop slots:=jsonb_set(slots,array[role],pg_temp.o_new(n,'Full scale '||n));n:=n+1;end loop;perform public.save_game_editor(pg_temp.o_command(128,slots));end$$;
do $$begin for n in 1..21 loop perform public.save_game_editor(pg_temp.o_command(200+n*2,jsonb_set(pg_temp.o_empty(),'{referee}',pg_temp.o_new(700+n,'Page official '||lpad(n::text,2,'0')))));end loop;end$$;
select pg_temp.o_assert(jsonb_array_length(public.list_game_officials('Page official',0)->'items')=20 and (public.list_game_officials('Page official',0)->>'hasMore')::boolean,'page 20');
select pg_temp.o_assert(jsonb_array_length(public.list_game_officials('Page official',20)->'items')=1 and not(public.list_game_officials('Page official',20)->>'hasMore')::boolean,'page remainder');
select pg_temp.o_error('select public.list_game_officials('''',-1)','PT400');
select pg_temp.o_error('select public.list_game_officials(repeat(''a'',161),0)','PT400');
select set_config('request.jwt.claim.sub','fd600000-0000-4000-8000-000000000099',true);
select pg_temp.o_error('select public.list_game_officials('''',0)','PT403');
select pg_temp.o_error(format('select public.get_game_editor(%L::uuid)',pg_temp.o_id(103)),'PT403');
select pg_temp.o_error(format('select public.save_game_editor(%L::jsonb)',pg_temp.o_command(102,jsonb_set(pg_temp.o_empty(),'{referee}',pg_temp.o_new(500,' João   Silva ')))),'PT403');
reset role;
select pg_temp.o_assert((select count(*)=count(distinct command_id) from private.game_officiating_commands),'unique receipts');
select pg_temp.o_assert(not exists(select 1 from private.game_commands where command_id=pg_temp.o_id(130)),'late failure leaves no legacy receipt');
select pg_temp.o_error('update private.game_officiating_commands set result=result','PT403');
select pg_temp.o_assert((select officiating_snapshot#>>'{referee,name}'='João Silva' from private.game_officiating_commands where command_id=pg_temp.o_id(102)),'saved scale remains in immutable history after clearing');
rollback;
